package com.huawei.finance.domain.wealthproduct;
import static org.assertj.core.api.Assertions.assertThat; import com.huawei.finance.contracts.model.Enums; import com.huawei.finance.contracts.model.GuardrailCheck; import com.huawei.finance.contracts.model.RiskLevel; import com.huawei.finance.contracts.model.UnifiedTask; import java.time.Instant; import java.util.List; import java.util.Map; import org.junit.jupiter.api.Test;
class WealthProductDomainAgentTest {@Test void doesNotInventRecommendation(){var agent=new WealthProductDomainAgent(ignored->new WealthProductPort.ProductView("W","稳健产品","理财","R2","比较基准","180天"));var result=agent.execute(task());assertThat(result.status()).isEqualTo(Enums.TaskStatus.SUCCESS);assertThat(result.resultPayload()).doesNotContainKeys("recommendation","purchaseAction");}private static UnifiedTask task(){return new UnifiedTask("t","trace",Enums.TaskSource.FAST_PATH,"查询理财","cap.wealth-product.product.query",Map.of(),RiskLevel.R0,Map.of(),GuardrailCheck.passed(),"idem",List.of(),Instant.now().plusSeconds(5));}}
